contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Takes a dummy uint parameter so the checker considers many inputs.
    // The property: whenever this contract is the current owner, calling owned() must not revert.
    function run(uint dummy) public payable {
        require(true);

        // Observe owner before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        // Make the call as a top-level statement and capture whether it reverted
        bool reverted;
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // If this contract was owner before the call, the call must not revert.
        assert(ownerBefore == address(this) ? (!reverted) : true);
    }

    receive() external payable { }
}

