pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(uint256 dummy) internal {
        vm.assume(true);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(ownerBefore == address(this) ? (!reverted) : true);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable { }
}
